import re,ast
s=open('/workspace/challenge.py').read()
K={}
for n in range(1,7):
    K[n]=ast.literal_eval(re.search(rf'^K{n} = (b.*)$', s, re.M).group(1))
iv=[int(c) for c in "0011101100111111000001100010001100000001111011011110010001010111000110101"]
M=73
def f(a,b,c,d):
    return (a&b&c&d | a&(b^1)&(c^1)&d | a&(b^1)&c&(d^1) | a&b&(c^1)&(d^1) | (a^1)&b&(c^1)&d | (a^1)&b&c&(d^1))
inp=[[0]*M for _ in range(M)]
fails=0
for i in range(M):
    ivb=iv[i]
    for p in range(M):
        for b in range(8):
            g=lambda n:(K[n][p]>>b)&1
            K1,K2,K3,K4,K5,K6=g(1),g(2),g(3),g(4),g(5),g(6)
            good=[]
            for x in (0,1):
                ok=True
                inner=f(x,ivb,K5,K6)
                for st in (0,1):
                    for k in (0,1):
                        t=f(k,inner,K3,K4)
                        o=f(st,t,K1,K2)
                        if o!=(st^k): ok=False
                if ok: good.append(x)
            if len(good)!=1: fails+=1; x=0
            else: x=good[0]
            inp[i][p] |= 0  # placeholder
            inp[i][p] |= (x<<b)
print("lanes without unique x:",fails)

